package io.arconia.dev.services.core.ssl;

import io.arconia.core.support.Incubating;

/**
 * Where the certificate a dev service presents over SSL comes from.
 */
@Incubating
public enum SslCertificate {

    /**
     * The certificate is configured through the {@code ssl} properties of the dev service:
     * a key store is required when SSL is enabled.
     */
    CONFIGURED,

    /**
     * The certificate is configured through the {@code ssl} properties when a key store is,
     * and generated by the container otherwise. Only for a container whose Spring Boot
     * connection details factory extracts the generated certificate when the {@code @Ssl}
     * annotation alone is declared, as the Elasticsearch one does.
     */
    CONFIGURED_OR_GENERATED

}
